head.b:skin:
:root{--bg:#07111f;--card:#0d1b2d;--card2:#10243b;--text:#eef6ff;--muted:#a9bbcf;--gold:#f4c95d;--blue:#4da3ff;--green:#2dd4a3}
*{box-sizing:border-box}body{margin:0;font-family:Tahoma,Arial,sans-serif;background:linear-gradient(180deg,#07111f,#0a1626 35%,#07111f);color:var(--text);line-height:1.9}
a{text-decoration:none;color:inherit}.topverse{background:#050b14;color:#f7d878;text-align:center;padding:13px;font-size:17px;border-bottom:1px solid #26384c}.topverse b{margin:0 12px}
nav{position:sticky;top:0;z-index:10;background:rgba(7,17,31,.92);backdrop-filter:blur(12px);border-bottom:1px solid #21344a}
.navin{max-width:1200px;margin:auto;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-weight:900;font-size:24px;color:#fff}.brand span{color:var(--gold)}.links{display:flex;gap:16px;flex-wrap:wrap;color:var(--muted);font-size:14px}
.hero{max-width:1200px;margin:auto;padding:80px 20px 55px;display:grid;grid-template-columns:1.3fr .7fr;gap:30px;align-items:center}.badge{display:inline-block;background:#12345a;color:#8fc4ff;padding:7px 14px;border-radius:50px}.hero h1{font-size:54px;line-height:1.2;margin:20px 0}.hero h1 span{color:var(--gold)}.hero p{font-size:19px;color:var(--muted);max-width:700px}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.btn{padding:13px 20px;border-radius:12px;font-weight:bold}.primary{background:var(--gold);color:#111}.secondary{border:1px solid #38536e}.heroCard{background:linear-gradient(145deg,#102a47,#0d1b2d);border:1px solid #2c4966;border-radius:24px;padding:28px;box-shadow:0 20px 60px #0006}.heroCard h3{color:var(--gold)}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.stat{background:#081523;padding:16px;border-radius:15px;text-align:center}.stat b{display:block;font-size:28px;color:var(--gold)}
section{max-width:1200px;margin:auto;padding:45px 20px}.sectionTitle{text-align:center;margin-bottom:30px}.sectionTitle h2{font-size:32px;margin:0}.sectionTitle p{color:var(--muted)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.course{background:var(--card);border:1px solid #203850;border-radius:20px;padding:22px;transition:.2s}.course:hover{transform:translateY(-5px);border-color:#4d83b6}.icon{font-size:38px}.course h3{margin:10px 0;color:#fff}.course p{color:var(--muted);font-size:14px}.tag{font-size:12px;background:#173352;color:#9bc8ff;padding:4px 9px;border-radius:20px;display:inline-block}
details{background:var(--card);border:1px solid #213c58;border-radius:18px;margin:14px 0;overflow:hidden}summary{cursor:pointer;padding:19px;font-size:19px;font-weight:bold;background:linear-gradient(90deg,#0f2741,#0c1b2d)}.lesson{padding:20px 22px;color:#dbe8f5}.lesson h4{color:var(--gold);font-size:18px;margin:12px 0}.lesson p,.lesson li{color:#c7d6e6}.lesson .box{background:#071421;border-right:4px solid var(--green);padding:14px;border-radius:10px;margin:15px 0}.quiz{background:#101d2d;border:1px dashed #476b8e;padding:15px;border-radius:12px;margin-top:14px}
.path{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}.step{background:#10243b;border:1px solid #284866;border-radius:14px;padding:14px;min-width:160px;text-align:center}.step b{color:var(--gold)}
footer{background:#040a12;border-top:1px solid #1b3045;padding:45px 20px;text-align:center;color:var(--muted)}.socials{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin:20px}.social{background:#10243b;padding:12px 18px;border-radius:12px;border:1px solid #284866}
.notice{max-width:900px;margin:10px auto 35px;background:#10243b;border:1px solid #2d5678;padding:18px;border-radius:14px;color:#cfe3f7}
@media(max-width:800px){.hero{grid-template-columns:1fr;padding-top:45px}.hero h1{font-size:38px}.links{display:none}}
